"""Constant-time bond dimension of the periodic comb across a tensor-train cut.

The comb c_x = [x = x0 mod r] on a register of size Q = B*C, presented across the
cut x = b + B*c, has Schmidt rank exactly min(C, r/gcd(r,B)) whenever r <= B.
The naive route to this number is a singular value decomposition costing
O(B*C*min(B,C)); the formula costs one Euclidean gcd, O(log r).
"""

from math import gcd
from typing import List, Tuple


def cut_period(order: int, block: int) -> int:
    """r / gcd(r, B): the least k >= 1 with r | B*k."""
    return order // gcd(order, block)


def comb_bond_dimension(order: int, block: int, blocks: int) -> int:
    """Exact Schmidt rank of the comb across the cut (valid for order <= block)."""
    return min(blocks, cut_period(order, block))


def output_bond_dimension(dual_period: int, block: int, blocks: int) -> int:
    """Exact Schmidt rank of the Fourier output, m = Q/r in place of r."""
    return min(blocks, cut_period(dual_period, block))


def compressible_cuts(q_size: int, order: int, threshold: int) -> List[Tuple[int, int, int]]:
    """All cuts (B, C, rank) of a register of size q_size with rank <= threshold."""
    result: List[Tuple[int, int, int]] = []
    for block in (d for d in range(1, q_size + 1) if q_size % d == 0):
        blocks = q_size // block
        rank = comb_bond_dimension(order, block, blocks)
        if rank <= threshold:
            result.append((block, blocks, rank))
    return result


def is_qubit_cut_compressible(order: int, exponent_bits: int) -> bool:
    """Is any power-of-two cut of a register of 2^exponent_bits able to compress?"""
    q_size = 2 ** exponent_bits
    return any(comb_bond_dimension(order, 2 ** k, q_size // 2 ** k) == 1
               for k in range(1, exponent_bits) if 2 ** k >= order)


if __name__ == "__main__":
    for order, block, blocks in ((5, 8, 8), (15, 16, 16), (6, 12, 6), (21, 32, 32)):
        print(f"r={order:3d} B={block:3d} C={blocks:3d} -> bond dimension "
              f"{comb_bond_dimension(order, block, blocks)}"
              f"   (cut period {cut_period(order, block)})")
    print("compressible cuts of Q=64 for r=5, threshold 2:",
          compressible_cuts(64, 5, 2))
    print("any compressing qubit cut for the odd order 21 in a 2^10 register?",
          is_qubit_cut_compressible(21, 10))
